import { useState } from "react";

export function Timer() {
  const [minutes, setMinutes] = useState(10);
  const [log, setLog] = useState([]);

  function addThree() {
    setMinutes((m) => m + 1);   // 11.
    setMinutes((m) => m + 1);   // 12.
    setMinutes((m) => m + 1);   // 13.
    console.log(minutes);       // still 10: this render's snapshot.
  }

  function record() {
    setLog((prev) => [...prev, `${minutes} min`]);   // new array, not push.
  }

  return (
    <div>
      <p>{minutes} minutes</p>
      <button type="button" onClick={addThree}>+3 minutes</button>
      <button type="button" onClick={record}>Record</button>
    </div>
  );
}
```

| Call | Queued effect |
|---|---|
| `setMinutes(5)`. | replace with 5. |
| `setMinutes(minutes + 1)`. | replace with snapshot + 1. |
| `setMinutes(m => m + 1)`. | add 1 to the latest queued value. |
| `log.push(x)`. | mutation: React may not re-render. |
| `setLog(prev => [...prev, x])`. | new array: re-renders. |

